import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';

const base = new URL('../src/romaji/', import.meta.url);
const manifest = JSON.parse(readFileSync(new URL('data/provenance.json', base), 'utf8'));
const check = process.argv.slice(2);
if (check.some((arg) => arg !== '--check') || check.length > 1) {
  throw new Error('Usage: node scripts/generate-conversions.mjs [--check]');
}
const blocks = [
  '// Generated by scripts/generate-conversions.mjs; do not edit.',
  '// C/Migemo conversion data, copyright (c) 2003-2026 MURAOKA Taro (KoRoN).',
  '// MIT license: see LICENSE-CMIGEMO. Source hashes: data/provenance.json.',
];
for (const [name, sha256] of Object.entries(manifest.files)) {
  const data = readFileSync(new URL(`data/${name}.dat`, base));
  if (createHash('sha256').update(data).digest('hex') !== sha256) {
    throw new Error(`Frozen conversion source changed: ${name}`);
  }
  const rows = [];
  for (const raw of data.toString('utf8').split('\n')) {
    // C's parser defines whitespace using ASCII isspace, not Unicode trim.
    let line = raw.replace(/^[\t\v\f\r ]+/, '');
    if (line.startsWith('##')) line = line.slice(1);
    else if (line.startsWith('#')) continue;
    if (!line) continue;
    const [key, value, remain = ''] = line.split(/[\t\v\f\r ]+/);
    if (!key || !value) throw new Error(`Invalid ${name} conversion row`);
    rows.push([key, value, remain]);
  }
  // romaji_add_entry discards longer keys when their prefix becomes terminal;
  // later longer keys are ignored. Keep exactly that source-order behavior.
  const accepted = new Map();
  for (const [key, value, remain] of rows) {
    if ([...accepted.keys()].some((prefix) => key.startsWith(prefix))) continue;
    for (const previous of accepted.keys()) {
      if (previous.startsWith(key)) accepted.delete(previous);
    }
    accepted.set(key, [value, remain]);
  }
  blocks.push('', '///|', `let ${name} : ConversionTable = make_table([`);
  for (const [key, [value, remain]] of accepted) {
    blocks.push(`  (${[key, value, remain].map((part) => JSON.stringify(part)).join(', ')}),`);
  }
  blocks.push('])');
}
const output = `${blocks.join('\n')}\n`;
const destination = new URL('tables.mbt', base);
if (check.length) {
  if (readFileSync(destination, 'utf8') !== output) throw new Error('Run node scripts/generate-conversions.mjs');
} else {
  writeFileSync(destination, output);
}
